type IProps<T extends keyof JSX.IntrinsicElements> = DynamicHtmlElementProps<T> & {
    inputRef?: React.Ref<Element>;
    element?: T;
    children?: ReactNode | undefined;
    // The kind of button, similar to how Bootstrap works.
    // See available classes for AccessibleButton for options.
    kind?: AccessibleButtonKind | string;
    // The ARIA role
    role?: string;
    // The tabIndex
    tabIndex?: number;
    disabled?: boolean;
    className?: string;
    triggerOnMouseDown?: boolean;
    onClick(e?: ButtonEvent): void | Promise<void>;
};

interface IAccessibleButtonProps extends React.InputHTMLAttributes<Element> {
    ref?: React.Ref<Element>;
}

/**
 * AccessibleButton is a generic wrapper for any element that should be treated
 * as a button.  Identifies the element as a button, setting proper tab
 * indexing and keyboard activation behavior.
 *
 * @param {Object} props  react element properties
 * @returns {Object} rendered react
 */
export default function AccessibleButton<T extends keyof JSX.IntrinsicElements>({
    element,
    onClick,
    children,
    kind,
    disabled,
    inputRef,
    className,
    onKeyDown,
    onKeyUp,
    triggerOnMouseDown,
    ...restProps
}: IProps<T>) {
    const newProps: IAccessibleButtonProps = restProps;
    if (disabled) {
        newProps["aria-disabled"] = true;
        newProps["disabled"] = true;
    } else {
        if (triggerOnMouseDown) {
            newProps.onMouseDown = onClick;
        } else {
            newProps.onClick = onClick;
            signOutButton = <AccessibleButton kind="danger_outline" onClick={this.onOwnDeviceSignOut}>
                { _t("Sign Out") }
            </AccessibleButton>;
        }

        const buttons = this.state.renaming ?
            <form className="mx_DevicesPanel_renameForm" onSubmit={this.onRenameSubmit}>
                <Field
                    label={_t("Display Name")}
                    type="text"
                    value={this.state.displayName}
                    autoComplete="off"
                    onChange={this.onChangeDisplayName}
                    autoFocus
                />
                <AccessibleButton onClick={this.onRenameSubmit} kind="confirm_sm" />
                <AccessibleButton onClick={this.onRenameCancel} kind="cancel_sm" />
            </form> :
            <React.Fragment>
                { signOutButton }
                { verifyButton }
                <AccessibleButton kind="primary_outline" onClick={this.onRename}>
                    { _t("Rename") }
                </AccessibleButton>
            </React.Fragment>;

        const deviceWithVerification = {
            ...this.props.device,
            isVerified: this.props.verified,
        };

        if (this.props.isOwnDevice) {
            return <div className={classNames("mx_DevicesPanel_device", "mx_DevicesPanel_myDevice")}>
                <div className="mx_DevicesPanel_deviceTrust">
                    <span className={"mx_DevicesPanel_icon mx_E2EIcon " + iconClass} />
                </div>
                <DeviceTile device={deviceWithVerification}>
                    { buttons }
                </DeviceTile>
            </div>;
        }

        return (
            <div className="mx_DevicesPanel_device">
                <SelectableDeviceTile device={deviceWithVerification} onClick={this.onDeviceToggled} isSelected={this.props.selected}>
                    { buttons }
                </SelectableDeviceTile>
            </div>
        );
    }
}

